// Работа с сохранённой сессией аккаунта БЕЗ открытия приложения (паролей нет):
// обновить токен по refresh_token и записать новую сессию обратно в .qa/auth/<id>.json
// (Supabase меняет refresh_token при каждом обновлении — старый повторно использовать нельзя).
import { APIRequestContext, expect } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';
import { SUPABASE_URL } from './api';

const AUTH_KEY = 'sb-wrqtmeohvmxzkgygkwul-auth-token';

type Session = { access_token: string; refresh_token: string; user: { id: string; email: string } } & Record<string, unknown>;

export const authFile = (id: string) => path.resolve(__dirname, '../../../auth', `${id}.json`);

function readState(id: string) {
  const file = authFile(id);
  if (!fs.existsSync(file)) throw new Error(`Нет сессии «${id}» (.qa/auth/${id}.json). Запусти npm run qa-login`);
  return JSON.parse(fs.readFileSync(file, 'utf8')) as { cookies: unknown[]; origins: { origin: string; localStorage: { name: string; value: string }[] }[] };
}

/** Сессия из файла (email, id пользователя, токены). */
export function readSession(id: string): Session {
  for (const o of readState(id).origins) {
    const item = o.localStorage.find((i) => i.name === AUTH_KEY);
    if (item) return JSON.parse(item.value) as Session;
  }
  throw new Error(`В .qa/auth/${id}.json нет ${AUTH_KEY}`);
}

/** Обновляет токен аккаунта и сохраняет новую сессию в его файл. Возвращает новый access token. */
export async function refreshSession(request: APIRequestContext, apikey: string, id: string): Promise<string> {
  const current = readSession(id);
  const res = await request.post(`${SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`, {
    headers: { apikey, 'content-type': 'application/json' },
    data: { refresh_token: current.refresh_token },
  });
  expect(res.ok(), `сессия «${id}» не обновилась (${res.status()}) — нужен qa-login`).toBeTruthy();
  const fresh = (await res.json()) as Session;
  const state = readState(id);
  for (const o of state.origins) {
    const item = o.localStorage.find((i) => i.name === AUTH_KEY);
    if (item) item.value = JSON.stringify({ ...current, ...fresh });
  }
  fs.writeFileSync(authFile(id), JSON.stringify(state, null, 2));
  return fresh.access_token;
}

/** GET к REST от имени конкретного токена. */
export function restAs(request: APIRequestContext, apikey: string, token: string) {
  const headers = { apikey, authorization: `Bearer ${token}` };
  return {
    get: (q: string) => request.get(`${SUPABASE_URL}/rest/v1/${q}`, { headers }),
    user: () => request.get(`${SUPABASE_URL}/auth/v1/user`, { headers }),
  };
}

/** Таблицы с данными бизнеса, которые проверяем старым токеном. */
export const DATA_TABLES = ['candidates', 'simulations', 'businesses', 'invitations'] as const;
